/*
 * GP4B reference implementation of the Top Spin 4 (Xbox 360, Swing_DLL.xex) ball model.
 * Module sha256 dfa71292f75a649773c280de7bc2688e6e47e473aba397c248fb4204c45fac44 (symbols.txt prefix ec79e191534b9b28),
 * all addresses are xex VAs.  Specification and evidence: work/gameplay-notes/gp4b.md ("Ball model spec").
 *
 * STATUS: DRAFT (not part of the matching build).  Compiles with   cc -std=c11 -Wall -Wextra -Werror -c
 *         and self-tests with  cc -std=c11 -Wall -Wextra -Werror -DGP4B_SELFTEST gp4b_ball_model.c -lm && ./a.out
 *
 * Exactness conventions (every numeric block below was produced mechanically from the PowerPC code and then
 * cross-checked against an emulation of the original machine code, see the notes, section "Validation"):
 *   - all arithmetic is IEEE binary32 with the ORIGINAL operation order; fused multiply-add instructions of the
 *     console (fmadds / fmsubs / fnmsubs) are written with fmaf(); the host compiler must not contract other
 *     expressions (-ffp-contract=off, which -std=c11 implies on GCC; do not use -ffast-math);
 *   - exp() is the CRT double exp (fn_88565118) rounded to float; log() is the CRT double log (fn_88563F20);
 *   - template data is read in the ORIGINAL big-endian byte layout (self-relative offsets), so a port can feed
 *     the shot-template table of the game data to this code unchanged.
 *   - `fsel`-style clamps are written as plain C compares; NaN inputs are not modelled (the original selects the
 *     "else" operand on NaN in the same way, but loops such as the tick quantiser would not terminate).
 *
 * Function name map (original -> here):
 *   fn_888AAEA8 arc_constants        fn_888AAE00 arc_end_constants     fn_888AAB98 speed2_initial
 *   fn_888AAA70 speed2_bounce        fn_888AACB8 speed2_initial_derivative
 *   ts4_bm_ball_apex_height_888AA968 apex_height          fn_888AB308 net_crossing_height   fn_888AB6C8 node_eval
 *   fn_888AB0E0 velocity_arrival     ts4_bm_ball_launch_velocity_888AB220 velocity_launch       ts4_bm_ball_arc1_position_888AB558 arc1_position
 *   ts4_bm_ball_arc2_position_888AD1C8 arc2_position        fn_888AB8D0 solve_kind_time       fn_888AC748/ACA68/ACDA8 solve_kind_speed
 *   fn_888AC688 secondary_dispatch   fn_888AB7B0/AC100/AC2B8/AC4A0/ABF10 secondary_*   fn_888AD0E8 solve_dispatch
 *   fn_889C2678 probe (solver entry) fn_889C1868 spin_blend            fn_889C0DC0 spin_accel
 *   fn_889C19F0 launch               fn_889C1AF8 launch_with_radius
 */
#include <math.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

#include "../gp4b_types.h"

/* ------------------------------------------------------------------------------------------------------------- */
/* constants (g_ts4_script_constants = 0x880D0F70 pool, lbl_8814B440 pool)                                        */
/* ------------------------------------------------------------------------------------------------------------- */
#define K_ONE        1.0f          /* pool+0x00 */
#define K_ZERO       0.0f          /* lbl_8814B440 */
#define K_HALF       0.5f          /* lbl_8814B910 */
#define K_TWO        2.0f          /* lbl_8814B45C */
#define K_HUNDRED    100.0f        /* pool+0x20 */
#define K_CM_TO_M    0x1.47ae14p-7f         /* pool+0x1BC */
#define K_TICK_DT    0x1.111112p-6f /* pool+0xE0 = 0x3C888889 = 1/60 */
#define K_TAU_LO     0x1.99999ap-4f          /* pool+0x2AC : lower flight-time bound (s) */
#define K_TAU_HI     0x1.466666p+2f          /* pool+0x68C : upper flight-time bound (s) */
#define K_MS_TO_KMH  0x1.ccccccp+1f          /* pool+0x2A4 */
#define K_KMH_SQ     0x1.3c0ca4p-4f  /* pool+0x30C = 0x3D9E0652 = 1/12.96 = (1/3.6)^2 */
#define K_FIVE       0x1.4p+2f          /* pool+0x1E0 */
#define K_X_EPS      0x1.0624dep-10f        /* pool+0x80  : |x| termination of the net-crossing search */
#define K_T_EPS      0x1.a36e2ep-14f       /* pool+0x458 : bracket width termination (1e-4) */

#define HASH_WOOD    0x9CAFB633u   /* ball mode / shot id "Wood" */
#define TPLK_A       GP4B_KIND_DROP_TIME
#define TPLK_B       GP4B_KIND_AVERAGE_SPEED
#define TPLK_C       GP4B_KIND_BOUNCE_SPEED
#define TPLK_D       GP4B_KIND_INITIAL_SPEED
#define TPLK_E       GP4B_KIND_APOGEE
#define NODE_TABLE2D GP4B_NODE_TABLE2D
#define NODE_CURVE20 GP4B_NODE_CURVE20
#define NODE_CONST   GP4B_NODE_CONST

static float xexp(float x) { return (float)exp((double)x); }
static float xlog(float x) { return (float)log((double)x); }

/* ------------------------------------------------------------------------------------------------------------- */
/* data access: the template table is big-endian with self-relative offsets                                       */
/* ------------------------------------------------------------------------------------------------------------- */
static uint32_t be32(const uint8_t *p) { return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3]; }
static int32_t bei32(const uint8_t *p) { return (int32_t)be32(p); }
static float bef32(const uint8_t *p) { uint32_t u = be32(p); float f; memcpy(&f, &u, 4); return f; }

/* fn_881899D8: curve of 16-byte keys {x0, x1, y0, y1}; header {i32 first_key_offset (-1 = none), i32 count}.
 * Picks the LAST key with x0 <= x (the first key if none) and returns y0 + clamp((x-x0)/(x1-x0), 0, 1) * (y1-y0). */
static float curve16_eval(float x, const uint8_t *c)
{
    int32_t first = bei32(c);
    const uint8_t *begin = (first == -1) ? NULL : c + first;
    const uint8_t *end = (first == -1) ? NULL : c + first + 16 * bei32(c + 4);
    const uint8_t *sel = begin, *cur = begin;
    while (cur != end) {
        if (bef32(cur) > x) break;
        sel = cur;
        cur += 16;
    }
    {
        float x0 = bef32(sel), x1 = bef32(sel + 4), y0 = bef32(sel + 8), y1 = bef32(sel + 12);
        float dx = x - x0, span = x1 - x0, dy = y1 - y0;
        float lo = (dx >= K_ZERO) ? dx : K_ZERO;              /* max(dx, 0) */
        float t = ((lo - span) >= K_ZERO) ? span : lo;         /* min(lo, span) */
        return fmaf(t / span, dy, y0);
    }
}

/* fn_8817A688: curve of 20-byte keys {x0, x1, y0, slope, (unused)}; same header.  y = y0 + slope * clamp(x-x0, 0, x1-x0). */
static float curve20_eval(float x, const uint8_t *c)
{
    int32_t first = bei32(c);
    const uint8_t *begin = (first == -1) ? NULL : c + first;
    const uint8_t *end = (first == -1) ? NULL : c + first + 20 * bei32(c + 4);
    const uint8_t *sel = begin, *cur = begin;
    while (cur != end) {
        if (bef32(cur) > x) break;
        sel = cur;
        cur += 20;
    }
    {
        float x0 = bef32(sel), x1 = bef32(sel + 4), y0 = bef32(sel + 8), slope = bef32(sel + 12);
        float dx = x - x0, span = x1 - x0;
        float t = ((dx - span) >= K_ZERO) ? span : dx;
        float u = (t >= K_ZERO) ? t : K_ZERO;
        return fmaf(u, slope, y0);
    }
}

/* fn_8826D278: 2-D table.  Header {i32 first_row_offset (-1 = none), i32 row_count}; rows are 16 bytes
 * {i32 key_off, i32 key_count, i32 ?, f32 a_key} where the first 8 bytes of a row are a curve16 header (relative to the
 * ROW) and a_key (row+0xC) is ascending.  Linear interpolation in `a` between the curve16 values at `b` of the two rows
 * enclosing `a`; clamps to the first/last row. */
static float table2d_eval(const uint8_t *tb, float a, float b)
{
    int32_t first = bei32(tb);
    const uint8_t *end = (first == -1) ? NULL : tb + 16 * bei32(tb + 4) + first;
    const uint8_t *hi = (first == -1) ? NULL : tb + first;
    const uint8_t *lo = hi;
    for (;;) {
        float d = a - bef32(hi + 12);
        union { float f; uint32_t u; } s; s.f = d;
        if (s.u & 0x80000000u) break;        /* a < key(hi) (sign bit of a - key) */
        lo = hi;
        hi += 16;
        if (hi == end) break;
    }
    if (lo == hi || hi == end) return curve16_eval(b, lo);
    {
        float vlo = curve16_eval(b, lo);
        float vhi = curve16_eval(b, hi);
        float d = a - bef32(lo + 12);
        float span = bef32(hi + 12) - bef32(lo + 12);
        if (d > K_ZERO) {
            if (d >= span) return vhi;
            return fmaf(d / span, vhi - vlo, vlo);
        }
        return vlo;
    }
}

/* fn_888AB6C8: evaluate a template element "node" {i32 rel, u32 type, u32 kind_hash} for a shot from p0 to p1 (metres).
 * x = horizontal distance |p1-p0| in cm, second table argument = p0.y in cm. */
static float node_eval(const uint8_t *node, const float p0[4], const float p1[4])
{
    float dx = p1[0] - p0[0];
    float dz = p1[2] - p0[2];
    float zz = dz * dz;
    float d = sqrtf(fmaf(dx, dx, zz));
    uint32_t type = be32(node + 4);
    int32_t rel = bei32(node);
    if (type == NODE_TABLE2D) return table2d_eval(node + rel, d * K_HUNDRED, p0[1] * K_HUNDRED);
    if (type == NODE_CURVE20) return curve20_eval(d * K_HUNDRED, node + rel);
    if (type == NODE_CONST) return bef32(node + rel);
    return K_ZERO;
}

/* ------------------------------------------------------------------------------------------------------------- */
/* closed-form arc maths (all H, mechanically derived)                                                            */
/* ------------------------------------------------------------------------------------------------------------- */
/* fn_888AAEA8: constants that depend on T, a4, g and the endpoints */
void gp4b_arc_constants(Gp4bBall *B)
{
    float t0 = B->a4;
    float t1 = B->T;
    float t2 = (t1 * t1);
    float t3 = 1.0f; /* const@880D0F70 */
    float t4 = (t3 / t0);
    B->inv_a4 = (t4);
    float t5 = (t3 / t1);
    B->inv_T = (t5);
    float t6 = (t4 * t1);
    B->k = (t6);
    float t7 = B->g;
    float t8 = (t5 * t5);
    float t9 = B->a4;
    float t10 = (t7 * t9);
    B->inv_T2 = (t8);
    B->g_a4 = (t10);
    float t11 = B->a4;
    float t12 = (t11 * t11);
    B->T_sq = (t2);
    B->a4_sq = (t12);
    float t13 = B->P1[0];
    float t15 = B->P1[2];
    float t17 = B->P0[0];
    float t18 = B->P0[1];
    float t19 = B->P0[2];
    float t21 = (t17 * t1);
    float t22 = (t18 * t1);
    float t23 = (t19 * t1);
    float t24 = (t13 * t1);
    B->p0x_T = (t21);
    float t25 = (t15 * t1);
    B->p1x_T = (t24);
    B->p0y_T = (t22);
    B->p0z_T = (t23);
    B->p1z_T = (t25);
}

/* fn_888AAE00: constants that depend on tau and the drift vector A */
void gp4b_arc_end_constants(Gp4bBall *B)
{
    float t0 = B->k;
    float t1 = B->tau;
    float t2 = (t0 * t1);
    float t3 = B->A[0];
    float t4 = B->A[1];
    float t5 = B->A[2];
    float t7 = (-t2);
    float t8 = xexp(t7);
    B->E = (t8);
    float t9 = 1.0f; /* const@880D0F70 */
    float t10 = (t8 - t9);
    float t11 = (t9 / t10);
    B->inv_E_m1 = (t11);
    float t12 = B->tau;
    float t13 = (t12 * t3);
    B->tauA[0] = (t13);
    float t14 = B->tau;
    float t15 = (t14 * t4);
    B->tauA[1] = (t15);
    float t16 = B->tau;
    float t17 = (t16 * t5);
    B->tauA[2] = (t17);
    float t18 = B->g_a4;
    float t19 = B->tau;
    float t20 = (t18 * t19);
    B->g_a4_tau = (t20);
}

/* fn_888AAB98: |v(0)|^2 = INITIAL (launch) speed^2 of arc 1 ((m/s)^2); this is what the commanded speed (km/h, ball+0x370) refers to */
float gp4b_speed2_initial(const Gp4bBall *B)
{
    float ret;
    float t0 = B->tau;
    float t1 = B->k;
    float t2 = (t1 * t0);
    float t3 = B->T;
    float t4 = B->P0[0];
    float t5 = B->P0[1];
    float t6 = B->P0[2];
    float t8 = B->P1[0];
    float t10 = B->P1[2];
    float t12 = B->A[0];
    float t13 = B->A[1];
    float t14 = B->A[2];
    float t16 = (-t2);
    float t17 = xexp(t16);
    float t18 = (t5 * t3);
    float t19 = (t14 * t0);
    float t20 = (t12 * t0);
    float t21 = B->inv_T;
    float t22 = (t14 * t21);
    float t23 = (t12 * t21);
    float t24 = B->g_a4;
    float t25 = B->inv_a4;
    float t26 = 1.0f; /* const@880D0F70 */
    float t27 = (t17 - t26);
    float t28 = fmaf(t13, t0, t18);
    float t29 = fmaf(t6, t3, t19);
    float t30 = fmaf(t4, t3, t20);
    float t31 = (t26 / t27);
    float t32 = fmaf(t24, t0, -t28);
    float t33 = fmaf(-t10, t3, t29);
    float t34 = fmaf(-t8, t3, t30);
    float t35 = (t32 * t25);
    float t36 = (t33 * t25);
    float t37 = (t34 * t25);
    float t38 = (t35 * t31);
    float t39 = fmaf(t36, t31, t22);
    float t40 = fmaf(t37, t31, t23);
    float t41 = fmaf(t13, t21, -t38);
    float t42 = fmaf(-t24, t21, t41);
    float t43 = (t42 * t42);
    float t44 = fmaf(t39, t39, t43);
    float t45 = fmaf(t40, t40, t44);
    ret = t45;
    return ret;
}

/* fn_888AAA70: |v(tau)|^2 = BOUNCE (arrival at the ground) speed^2 of arc 1 ((m/s)^2) */
float gp4b_speed2_bounce(const Gp4bBall *B)
{
    float ret;
    float t0 = B->T;
    float t1 = B->inv_a4;
    float t2 = (t1 * t0);
    float t3 = B->tau;
    float t4 = B->P0[0];
    float t5 = B->P0[1];
    float t6 = B->P0[2];
    float t8 = B->P1[0];
    float t10 = B->P1[2];
    float t12 = B->A[0];
    float t13 = B->A[1];
    float t14 = B->A[2];
    float t16 = (t2 * t3);
    float t17 = (-t16);
    float t18 = xexp(t17);
    float t19 = (t5 * t0);
    float t20 = (t14 * t3);
    float t21 = (t12 * t3);
    float t22 = B->inv_T;
    float t23 = (t14 * t22);
    float t24 = (t12 * t22);
    float t25 = B->g_a4;
    float t26 = 1.0f; /* const@880D0F70 */
    float t27 = (t18 * t1);
    float t28 = fmaf(t13, t3, t19);
    float t29 = (t18 - t26);
    float t30 = fmaf(t6, t0, t20);
    float t31 = fmaf(t4, t0, t21);
    float t32 = fmaf(t25, t3, -t28);
    float t33 = (t26 / t29);
    float t34 = fmaf(-t10, t0, t30);
    float t35 = fmaf(-t8, t0, t31);
    float t36 = (t32 * t27);
    float t37 = (t34 * t27);
    float t38 = (t35 * t27);
    float t39 = (t36 * t33);
    float t40 = fmaf(t37, t33, t23);
    float t41 = fmaf(t38, t33, t24);
    float t42 = fmaf(t13, t22, -t39);
    float t43 = fmaf(-t25, t22, t42);
    float t44 = (t43 * t43);
    float t45 = fmaf(t40, t40, t44);
    float t46 = fmaf(t41, t41, t45);
    ret = t46;
    return ret;
}

/* fn_888AACB8: d(initial speed^2) / d tau  (sign decides the min-speed bisection: slowest possible shot) */
float gp4b_speed2_initial_derivative(const Gp4bBall *B)
{
    float ret;
    float t0 = B->tau;
    float t1 = B->k;
    float t2 = B->p0x_T;
    float t3 = (t1 * t0);
    float t4 = B->p1x_T;
    float t5 = B->inv_a4;
    float t6 = B->A[0];
    float t7 = B->A[1];
    float t8 = B->A[2];
    float t10 = fmaf(t6, t0, t2);
    float t11 = (-t3);
    float t12 = (t10 - t4);
    float t13 = xexp(t11);
    float t14 = B->p0y_T;
    float t15 = B->inv_a4;
    float t16 = fmaf(t7, t0, t14);
    float t17 = B->k;
    float t18 = 1.0f; /* const@880D0F70 */
    float t19 = (t15 * t17);
    float t20 = B->p0z_T;
    float t21 = B->g_a4;
    float t22 = fmaf(t8, t0, t20);
    float t23 = (t21 - t7);
    float t24 = B->p1z_T;
    float t25 = (t13 - t18);
    float t26 = B->inv_T;
    float t27 = (t8 * t26);
    float t28 = 2.0f; /* const@8814B45C */
    float t29 = (t6 * t26);
    float t30 = fmaf(t21, t0, -t16);
    float t31 = (t19 * t13);
    float t32 = (t22 - t24);
    float t33 = (t18 / t25);
    float t34 = (t25 * t25);
    float t35 = (t30 * t31);
    float t36 = (t32 * t31);
    float t37 = (t30 * t33);
    float t38 = (t23 * t33);
    float t39 = (t8 * t33);
    float t40 = (t18 / t34);
    float t41 = (t32 * t33);
    float t42 = (t6 * t33);
    float t43 = (t33 * t5);
    float t44 = (t37 * t5);
    float t45 = (t38 * t5);
    float t46 = (t39 * t5);
    float t47 = (t31 * t40);
    float t48 = fmaf(t41, t5, t27);
    float t49 = fmaf(t43, t12, t29);
    float t50 = fmaf(t7, t26, -t44);
    float t51 = (-t45);
    float t52 = fmaf(t36, t40, t46);
    float t53 = (t47 * t12);
    float t54 = fmaf(-t21, t26, t50);
    float t55 = fmaf(-t35, t40, t51);
    float t56 = (t52 * t48);
    float t57 = fmaf(t42, t5, t53);
    float t58 = fmaf(t55, t54, t56);
    float t59 = fmaf(t57, t49, t58);
    float t60 = (t59 * t28);
    ret = t60;
    return ret;
}

/* ts4_bm_ball_apex_height_888AA968: apex height (m) of arc 1 for flight time tt (uses the constants of gp4b_arc_constants only) */
float gp4b_apex_height(const Gp4bBall *B, float tt)
{
    float ret;
    float t0 = B->A[1];
    float t1 = B->P0[1];
    float t2 = (t0 * tt);
    float t3 = B->T;
    float t4 = (t1 * t3);
    float t5 = B->k;
    float t6 = B->g_a4;
    float t7 = (t5 * tt);
    float t8 = (tt * t6);
    float t9 = B->a4;
    float t10 = B->g;
    float t11 = (t2 + t4);
    float t12 = (-t7);
    float t13 = (t8 - t11);
    float t14 = xexp(t12);
    float t15 = B->g_a4;
    float t16 = B->inv_T;
    float t17 = B->T_sq;
    float t18 = 1.0f; /* const@880D0F70 */
    float t19 = (t18 / t17);
    float t20 = -1.0f; /* const@880D0FA8 */
    float t21 = (t20 / t13);
    float t22 = fmaf(t14, t0, -t0);
    float t23 = (t14 - t18);
    float t24 = (t16 * t21);
    float t25 = fmaf(-t15, t14, t22);
    float t26 = (t18 / t23);
    float t27 = (t25 + t15);
    float t28 = (t27 * t9);
    float t29 = (t24 * t28);
    float t30 = (-t29);
    float t31 = xlog(t30);
    float t32 = B->a4_sq;
    float t33 = (t21 * t28);
    float t34 = (t8 - t2);
    float t35 = (t31 * t0);
    float t36 = (t33 * t26);
    float t37 = (t32 * t31);
    float t38 = fmaf(-t14, t4, t34);
    float t39 = (t35 * t9);
    float t40 = (t37 * t19);
    float t41 = (t38 * t16);
    float t42 = fmaf(t36, t13, t39);
    float t43 = (t42 * t19);
    float t44 = fmaf(t40, t10, -t43);
    float t45 = fmaf(-t41, t26, t44);
    ret = t45;
    return ret;
}

/* fn_888AB0E0: velocity of arc 1 at t = tau (m/s); also the incoming velocity of the first bounce */
void gp4b_velocity_arrival(const Gp4bBall *B, float out[4])
{
    float t0 = B->T;
    float t1 = B->inv_a4;
    float t2 = (t1 * t0);
    float t3 = B->tau;
    float t4 = B->P0[0];
    float t5 = B->P0[1];
    float t6 = B->P0[2];
    float t8 = B->P1[0];
    float t10 = B->P1[2];
    float t12 = B->A[0];
    float t13 = B->A[1];
    float t14 = B->A[2];
    float t16 = (t2 * t3);
    float t17 = (-t16);
    float t18 = xexp(t17);
    float t19 = (t13 * t3);
    float t20 = (t12 * t3);
    float t21 = B->inv_T;
    float t22 = B->g_a4;
    float t23 = (t14 * t3);
    float t24 = 1.0f; /* const@880D0F70 */
    float t25 = (t18 * t1);
    float t26 = fmaf(t5, t0, t19);
    float t27 = fmaf(t4, t0, t20);
    float t28 = (t12 * t21);
    float t29 = 0.0f; /* const@8814B440 */
    float t30 = (t14 * t21);
    float t31 = (t18 - t24);
    float t32 = fmaf(t6, t0, t23);
    float t33 = fmaf(t22, t3, -t26);
    float t34 = fmaf(-t8, t0, t27);
    float t35 = (t24 / t31);
    float t36 = fmaf(-t10, t0, t32);
    float t37 = (t33 * t25);
    float t38 = (t34 * t25);
    float t39 = (t36 * t25);
    float t40 = (t37 * t35);
    float t41 = fmaf(t38, t35, t28);
    float t42 = fmaf(t39, t35, t30);
    float t43 = fmaf(t13, t21, -t40);
    float t44 = fmaf(-t22, t21, t43);
    out[0] = (t41);
    out[1] = (t44);
    out[2] = (t42);
    out[3] = (t29);
}

/* ts4_bm_ball_launch_velocity_888AB220: velocity of arc 1 at t = 0 (m/s) */
void gp4b_velocity_launch(const Gp4bBall *B, float out[4])
{
    float t0 = B->tau;
    float t1 = B->T;
    float t2 = B->g_a4;
    float t3 = B->inv_T;
    float t4 = B->inv_E_m1;
    float t5 = B->P0[0];
    float t6 = B->P0[1];
    float t7 = B->P0[2];
    float t9 = B->P1[0];
    float t11 = B->P1[2];
    float t13 = B->A[0];
    float t14 = B->A[1];
    float t15 = B->A[2];
    float t17 = (t13 * t0);
    float t18 = (t14 - t2);
    float t19 = 0.0f; /* const@8814B440 */
    float t20 = (t6 * t1);
    float t21 = (t5 - t9);
    float t22 = B->inv_a4;
    float t23 = (t7 - t11);
    float t24 = (t15 * t0);
    float t25 = (t3 * t13);
    float t26 = (t3 * t15);
    float t27 = (t18 * t3);
    float t28 = fmaf(t18, t0, t20);
    float t29 = fmaf(t21, t1, t17);
    float t30 = fmaf(t23, t1, t24);
    float t31 = (t28 * t4);
    float t32 = (t29 * t4);
    float t33 = (t30 * t4);
    float t34 = fmaf(t31, t22, t27);
    float t35 = fmaf(t32, t22, t25);
    float t36 = fmaf(t33, t22, t26);
    out[0] = (t35);
    out[1] = (t34);
    out[2] = (t36);
    out[3] = (t19);
}

/* ts4_bm_ball_arc1_position_888AB558: arc-1 position at t = (tick - tick_prev) * dt (dt = generator +4 = 1/60) -> B->pos (xyz) */
void gp4b_arc1_position(float dt, Gp4bBall *B)
{
    float cnt = (float)(B->tick - B->tick_prev);
    float pos[3];
    float t0 = dt;
    float t1 = B->k;
    float t2 = B->A[0];
    float t3 = B->A[1];
    float t4 = B->A[2];
    float t6 = (cnt * t0);
    float t7 = (t1 * t6);
    float t8 = (-t7);
    float t9 = xexp(t8);
    float t10 = B->p0y_T;
    float t11 = B->tauA[1];
    float t12 = (t11 + t10);
    float t13 = B->g_a4_tau;
    float t14 = B->tauA[0];
    float t15 = (t11 - t13);
    float t16 = B->p1x_T;
    float t17 = B->p0x_T;
    float t18 = (t14 - t16);
    float t19 = B->tauA[2];
    float t20 = (t17 + t14);
    float t21 = B->p1z_T;
    float t22 = B->p0z_T;
    float t23 = (t19 - t21);
    float t24 = (t22 + t19);
    float t25 = B->inv_T;
    float t26 = (t25 * t6);
    float t27 = B->E;
    float t28 = (t12 - t13);
    float t29 = (t2 * t6);
    float t30 = B->inv_E_m1;
    float t31 = (t4 * t6);
    float t33 = fmaf(t27, t17, t18);
    float t34 = (t20 - t16);
    float t35 = fmaf(t10, t27, t15);
    float t36 = B->g_a4;
    float t37 = fmaf(t22, t27, t23);
    float t38 = (t24 - t21);
    float t39 = (t28 * t30);
    float t40 = fmaf(-t34, t9, t33);
    float t41 = (t35 * t30);
    float t42 = fmaf(-t38, t9, t37);
    float t43 = (t39 * t25);
    float t44 = fmaf(t40, t30, t29);
    float t45 = fmaf(t42, t30, t31);
    float t46 = (t43 * t9);
    float t47 = (t44 * t25);
    float t48 = (t45 * t25);
    float t49 = fmaf(t3, t26, -t46);
    float t50 = fmaf(-t36, t26, t49);
    float t51 = fmaf(t41, t25, t50);
    pos[0] = t47;
    pos[1] = t51;
    pos[2] = t48;
    B->pos[0] = pos[0]; B->pos[1] = pos[1]; B->pos[2] = pos[2]; B->pos[3] = 0.0f;
}

/* ts4_bm_ball_arc2_position_888AD1C8: arc-2 position (initial value form from arc2_pos / arc2_vel) -> B->pos (xyz) */
void gp4b_arc2_position(float dt, Gp4bBall *B)
{
    float cnt = (float)(B->tick - B->tick_prev);
    float pos[3];
    float t0 = dt;
    float t1 = B->k;
    float t2 = B->a4;
    float t3 = B->g;
    float t4 = B->T;
    float t5 = B->arc2_pos[0];
    float t6 = B->arc2_pos[1];
    float t7 = B->arc2_pos[2];
    float t9 = B->arc2_vel[0];
    float t10 = B->arc2_vel[1];
    float t11 = B->arc2_vel[2];
    float t13 = B->A[0];
    float t14 = B->A[1];
    float t15 = B->A[2];
    float t17 = (cnt * t0);
    float t18 = (t1 * t17);
    float t19 = (-t18);
    float t20 = xexp(t19);
    float t21 = (t10 * t4);
    float t22 = (t13 * t2);
    float t23 = (t15 * t2);
    float t24 = (t9 * t4);
    float t25 = B->g_a4;
    float t26 = (t11 * t4);
    float t27 = B->T_sq;
    float t28 = (t27 * t6);
    float t29 = B->inv_T;
    float t30 = (t29 * t17);
    float t31 = (t25 + t21);
    float t32 = fmaf(t27, t5, -t22);
    float t34 = fmaf(t27, t7, -t23);
    float t35 = (t24 - t13);
    float t36 = B->inv_T2;
    float t37 = (t26 - t15);
    float t38 = B->a4_sq;
    float t39 = fmaf(t21, t2, t28);
    float t40 = (t13 * t30);
    float t41 = (t31 - t14);
    float t42 = fmaf(t24, t2, t32);
    float t43 = fmaf(t26, t2, t34);
    float t44 = (t35 * t20);
    float t45 = (t37 * t20);
    float t46 = (t15 * t30);
    float t47 = fmaf(-t14, t2, t39);
    float t48 = (t41 * t36);
    float t49 = fmaf(-t44, t2, t42);
    float t50 = fmaf(-t45, t2, t43);
    float t51 = (t48 * t20);
    float t52 = fmaf(t38, t3, t47);
    float t53 = fmaf(t49, t36, t40);
    float t54 = fmaf(t50, t36, t46);
    float t55 = (t51 * t2);
    float t56 = fmaf(t14, t30, -t55);
    float t57 = fmaf(-t25, t30, t56);
    float t58 = fmaf(t52, t36, t57);
    pos[0] = t53;
    pos[1] = t58;
    pos[2] = t54;
    B->pos[0] = pos[0]; B->pos[1] = pos[1]; B->pos[2] = pos[2]; B->pos[3] = 0.0f;
}

/* fn_888AB308: height (m) of arc 1 at its x = 0 crossing (net plane): bisection on the sign of x(t) over [0, tau]
 * (or [tau, 0] when P0.x <= 0), 4 steps per round, at most 375 rounds, stopping when |x| <= 1e-3 or the bracket < 1e-4.
 * NOTE: it uses E / tauA / g_a4_tau of the LAST gp4b_arc_end_constants call, not of B->tau (original behaviour). */
float gp4b_net_crossing_height(const Gp4bBall *B)
{
    int pos = B->P0[0] > K_ZERO;
    float lo = pos ? K_ZERO : B->tau;                    /* f28 */
    float hi = pos ? B->tau : K_ZERO;                    /* f29 */
    float tx = B->tauA[0];                               /* tau * A.x */
    float f10 = tx + B->p0x_T;
    float f8 = tx - B->p1x_T;
    float f27 = B->inv_T * B->A[0];
    float f3 = f10 - B->p1x_T;
    float f2 = fmaf(B->p0x_T, B->E, f8);
    float f1 = f3 * B->inv_T;
    float f12 = f2 * B->inv_T;
    float f11 = f1 * B->inv_E_m1;
    float f26 = f12 * B->inv_E_m1;
    float f25 = -f11;
    float t = K_ZERO, e = K_ZERO, ax = K_ONE;           /* f31, f0, f13 */
    int round = 0;
    while (ax > K_X_EPS) {
        int i;
        float w;
        for (i = 0; i < 4; i++) {
            float x;
            t = (hi + lo) * K_HALF;
            e = xexp(-(B->k * t));
            x = fmaf(f27, t, f25 * e) + f26;
            if (x >= K_ZERO) lo = t;
            if (!(x >= K_ZERO)) hi = t;
            ax = (x >= K_ZERO) ? x : -x;
        }
        w = hi - lo;
        w = (w >= K_ZERO) ? w : -w;
        if (w < K_T_EPS) break;
        if (++round >= 0x177) break;
    }
    {
        float a = B->p0y_T;
        float b = B->tauA[1];
        float c = b + a;
        float d = B->g_a4_tau;
        float f8b = b - d;
        float st = B->inv_T * t;
        float f2b = c - d;
        float f1b = fmaf(a, B->E, f8b);
        float f13b = f2b * B->inv_E_m1;
        float f12b = f1b * B->inv_E_m1;
        float f11b = f13b * B->inv_T;
        float f10b = f11b * e;
        float f9b = fmaf(B->A[1], st, -f10b);
        float f8c = fmaf(-B->g_a4, st, f9b);
        return fmaf(f12b, B->inv_T, f8c);
    }
}

/* ------------------------------------------------------------------------------------------------------------- */
/* flight-time (tau) solvers                                                                                      */
/* ------------------------------------------------------------------------------------------------------------- */
/* the clamp used all over the solvers: clamp(1 - blend_c0c, 0, 1) */
static float blend_weight(const Gp4bBall *B)
{
    float w = K_ONE - B->blend_c0c;
    float lo = (w >= K_ZERO) ? w : K_ZERO;
    return ((lo - K_ONE) >= K_ZERO) ? K_ONE : lo;
}

/* quantise B->tau to whole 1/60 s ticks by repeated subtraction: B->tau = n * dt (by repeated addition), B->bounce_tick = n */
static void quantise_tau(Gp4bBall *B)
{
    float x = B->tau, acc = K_ZERO;
    uint32_t n = 0;
    if (!(x < K_TICK_DT)) {
        do { x = x - K_TICK_DT; n++; acc = acc + K_TICK_DT; } while (!(x < K_TICK_DT));
    }
    B->tau = acc;
    B->bounce_tick = n;
}

typedef float (*Gp4bMetric)(const Gp4bBall *);

/* net-clearance threshold: top of the net + ball radius when planned, else the commanded height, plus 1 cm */
static float net_threshold(const Gp4bBall *B)
{
    float top = B->planned ? (B->radius_cm + B->net_height_cm) * K_CM_TO_M : B->aim_height;
    return top + K_CM_TO_M;
}


/* fn_888AB8D0  (primary kind "DropTime" 0x5D90675B: tau comes from the template curve when the shot is planned).
 * tpl = shot-template row + 0x18.  O = result struct.  B->tau / B->bounce_tick / O->* are the outputs. */
void gp4b_solve_kind_time(Gp4bBall *B, const uint8_t *tpl, Gp4bSolve *O)
{
    float lo, hi, mid, desired;
    int i;
    uint8_t planned = B->planned;
    uint32_t kind2 = be32(tpl + 0x14);
    float g0 = node_eval(tpl, B->P0, B->P1);              /* flight-time guess from the distance/height curve */
    B->tau = g0;
    O->tau = g0;
    if (!planned) {
        /* (1) tau of the slowest possible shot (minimum INITIAL speed): d(v0^2)/dtau changes sign there */
        B->tau = K_TAU_HI;
        lo = K_TAU_LO; hi = K_TAU_HI;
        for (i = 0; i < 20; i++) {
            mid = (hi + lo) * K_HALF;
            B->tau = mid;
            if (gp4b_speed2_initial_derivative(B) > K_ZERO) hi = mid; else lo = mid;
        }
        mid = (hi + lo) * K_HALF;
        O->tau_min = mid;
        B->tau = mid;
        {
            /* (2) if the minimum initial speed is below the commanded one, solve |v(0)|^2 = (speed_kmh/3.6)^2 on [0.1, tau_min] */
            float v2 = gp4b_speed2_initial(B);
            float dd = K_ZERO - B->speed_kmh;               /* fsqrts(pool double 0.0) - speed: the 0.0 is in the image */
            float target = (dd * dd) * K_KMH_SQ;
            float tmin = mid;
            if (!(v2 > target)) {
                lo = K_TAU_LO; hi = tmin;
                for (i = 0; i < 20; i++) {
                    mid = (hi + lo) * K_HALF;
                    B->tau = mid;
                    if (gp4b_speed2_initial(B) < target) hi = mid; else lo = mid;
                }
                O->tau = (hi + lo) * K_HALF;
            } else {
                O->tau = tmin;
            }
        }
    }
    if (B->shot_id != HASH_WOOD) {
        float thr = net_threshold(B);
        float ht;
        gp4b_arc_end_constants(B);
        ht = gp4b_net_crossing_height(B);
        O->raised = 0;
        if (ht < thr && planned) {
            /* raise tau (up to +2 s) until the arc clears the net */
            O->raised = 1;
            lo = B->tau;
            hi = lo + K_TWO;
            for (i = 0; i < 20; i++) {
                mid = (hi + lo) * K_HALF;
                B->tau = mid;
                gp4b_arc_end_constants(B);
                ht = gp4b_net_crossing_height(B);
                if (ht > thr) hi = mid; else lo = mid;
            }
            O->tau = (hi + lo) * K_HALF;
        }
    }
    /* secondary (element-1) stage, only the two kinds below exist inline in this routine */
    desired = O->tau;   /* ASM: stack garbage for any other kind2 (never used by game data, presumably) */
    if (kind2 == TPLK_A) {
        float g = node_eval(tpl + 0xC, B->P0, B->P1);
        desired = g + O->tau;
    } else if (kind2 == TPLK_E) {
        float apex = gp4b_apex_height(B, B->tau);
        float g = node_eval(tpl + 0xC, B->P0, B->P1);
        float target;
        B->tau = K_TAU_HI;
        target = g + apex;
        lo = K_TAU_LO; hi = K_TAU_HI;
        for (i = 0; i < 20; i++) {
            mid = (hi + lo) * K_HALF;
            B->tau = mid;
            if (gp4b_apex_height(B, mid) > target) hi = mid; else lo = mid;
        }
        desired = (hi + lo) * K_HALF;
    }
    if (planned) {
        float w = blend_weight(B);
        float base = O->tau;
        float d = desired - base;
        float t = w * d;
        B->tau = base + t;
        {
            float v2 = gp4b_speed2_initial(B);
            O->initial_kmh = sqrtf(v2) * K_MS_TO_KMH;
            O->tau_final = B->tau;
        }
        quantise_tau(B);
        O->net_height = gp4b_net_crossing_height(B);
    } else {
        float v2 = gp4b_speed2_initial(B);
        O->tau_final = O->tau;
        O->initial_kmh = sqrtf(v2) * K_MS_TO_KMH;
        quantise_tau(B);
        O->net_height = gp4b_net_crossing_height(B);
    }
}

/* ---- secondary stage fn_888AC688 -> one of five routines, selected by the kind hash of template element 1 (tpl+0x14) ----
 * Common inputs from the primary solver result O: tauA = O->raised ? O->tau_raised : O->tau.  All of them end in
 * B->tau = quantised(tauA + w * (tauB - tauA)) with w = blend_weight(B) and B->bounce_tick = ticks. */
static float tau_a(const Gp4bSolve *O) { return O->raised ? O->tau_raised : O->tau; }

static int secondary_prologue(Gp4bBall *B, const Gp4bSolve *O)
{
    if (!O->has_min) { B->tau = K_ONE; return 1; }
    if (O->net_unreachable) { B->tau = O->tau_raised; return 1; }
    return 0;
}

/* fn_888AB7B0 (element-1 kind "DropTime"): tauB = tauA + curve */
static void secondary_A(Gp4bBall *B, const uint8_t *tpl, const Gp4bSolve *O)
{
    float ta = O->raised ? O->tau_raised : O->tau;
    float w = blend_weight(B);
    float g = node_eval(tpl + 0xC, B->P0, B->P1);
    float tb = g + ta;
    float d = tb - ta;
    float m = d * w;
    B->tau = m + ta;
    quantise_tau(B);
}

/* generic body of fn_888AC100 (AverageSpeed, metric constant 0) / AC2B8 (InitialSpeed) / AC4A0 (BounceSpeed): metric-driven tauB */
static void secondary_metric(Gp4bBall *B, const uint8_t *tpl, const Gp4bSolve *O, Gp4bMetric metric)
{
    float ta, tmin, tb, target, lo, hi;
    int i;
    if (secondary_prologue(B, O)) return;
    ta = tau_a(O);
    tmin = O->tau_min;
    if (metric) {
        float m0, m1, g, dd;
        B->tau = ta;
        m0 = metric(B);
        B->tau = tmin;
        m1 = metric(B);
        g = node_eval(tpl + 0xC, B->P0, B->P1);
        {
            float sq = sqrtf(m0 * 0x1.9eb852p+3f);              /* pool+0x308 = 12.96 = 3.6^2: initial/bounce speed (km/h) of tauA */
            dd = sq - g;
        }
        target = (dd * dd) * K_KMH_SQ;
        tb = tmin;
        if (!(m1 > target)) {
            lo = ta; hi = tmin;
            for (i = 0; i < 20; i++) {
                float mid = (hi + lo) * K_HALF;
                B->tau = mid;
                if (target > metric(B)) hi = mid; else lo = mid;
            }
            tb = (hi + lo) * K_HALF;
        }
    } else {
        float g, dd;
        B->tau = tmin;
        g = node_eval(tpl + 0xC, B->P0, B->P1);
        dd = K_ZERO - g;                                 /* fsqrts(pool double 0.0) - g */
        target = (dd * dd) * K_KMH_SQ;
        tb = tmin;
        if (target >= K_ZERO) {
            lo = ta; hi = tmin;
            for (i = 0; i < 20; i++) {
                float mid = (hi + lo) * K_HALF;
                B->tau = mid;
                if (target > K_ZERO) hi = mid; else lo = mid;
            }
            tb = (hi + lo) * K_HALF;
        }
    }
    {
        float w = blend_weight(B);
        B->tau = fmaf(w, tb - ta, ta);
    }
    quantise_tau(B);
}

/* fn_888ABF10 (element-1 kind "Apogee"): tauB solves apex(tauB) = apex(tauA) + curve (clamped to tau_min) */
static void secondary_apex(Gp4bBall *B, const uint8_t *tpl, const Gp4bSolve *O)
{
    float ta, tmin, tb, apex_a, apex_m, g, lim, lo, hi;
    int i;
    if (secondary_prologue(B, O)) return;
    ta = tau_a(O);
    tmin = O->tau_min;
    B->tau = ta;
    apex_a = -gp4b_apex_height(B, ta);
    B->tau = tmin;
    apex_m = -gp4b_apex_height(B, tmin);
    g = node_eval(tpl + 0xC, B->P0, B->P1);
    lim = apex_a - g;
    tb = tmin;
    if (!(apex_m > lim)) {
        hi = tmin; lo = ta;
        for (i = 0; i < 20; i++) {
            float mid = (hi + lo) * K_HALF;
            B->tau = mid;
            if (lim > -gp4b_apex_height(B, mid)) hi = mid; else lo = mid;
        }
        tb = (hi + lo) * K_HALF;
    }
    {
        float w = blend_weight(B);
        B->tau = fmaf(w, tb - ta, ta);
    }
    quantise_tau(B);
}

/* fn_888AC688 */
void gp4b_secondary_dispatch(Gp4bBall *B, const uint8_t *tpl, const Gp4bSolve *O)
{
    uint32_t k = be32(tpl + 0x14);
    if (k == TPLK_A) secondary_A(B, tpl, O);
    else if (k == TPLK_B) secondary_metric(B, tpl, O, NULL);
    else if (k == TPLK_C) secondary_metric(B, tpl, O, gp4b_speed2_bounce);
    else if (k == TPLK_D) secondary_metric(B, tpl, O, gp4b_speed2_initial);
    else if (k == TPLK_E) secondary_apex(B, tpl, O);
    gp4b_arc_constants(B);
}

/* fn_888AC748 / fn_888ACA68 / fn_888ACDA8 (primary kinds AverageSpeed 0x2DB3EB6F / InitialSpeed 0xC1965E5C / BounceSpeed 0x50B89452): the same routine with a
 * different metric: none ("AverageSpeed": stub, constant 0), initial speed^2 ("InitialSpeed"), bounce speed^2 ("BounceSpeed").  The target speed is the commanded B->speed_kmh
 * (probe) or the template curve (planned).  O->metric_kmh = sqrt(metric(B))*3.6 at the final tau. */
void gp4b_solve_kind_speed(Gp4bBall *B, const uint8_t *tpl, Gp4bSolve *O, Gp4bMetric metric)
{
    float lo, hi, mid, tmin, thr, ht, tgt, target, dd, m0;
    int i;
    uint8_t planned = B->planned;
    B->tau = K_TAU_LO;
    O->has_min = (gp4b_speed2_initial_derivative(B) < K_ZERO);
    if (!O->has_min) return;
    B->tau = K_TAU_HI;
    lo = K_TAU_LO; hi = K_TAU_HI;
    for (i = 0; i < 20; i++) {
        mid = (hi + lo) * K_HALF;
        B->tau = mid;
        if (gp4b_speed2_initial_derivative(B) > K_ZERO) hi = mid; else lo = mid;
    }
    tmin = (hi + lo) * K_HALF;
    O->tau_min = tmin;
    B->tau = tmin;
    m0 = metric ? metric(B) : K_ZERO;
    tgt = planned ? node_eval(tpl, B->P0, B->P1) : B->speed_kmh;
    dd = K_ZERO - tgt;                                  /* fsqrts(pool double 0.0) - tgt */
    target = (dd * dd) * K_KMH_SQ;
    if (metric ? !(m0 > target) : (target >= K_ZERO)) {
        lo = K_TAU_LO; hi = tmin;
        for (i = 0; i < 20; i++) {
            mid = (hi + lo) * K_HALF;
            B->tau = mid;
            if ((metric ? metric(B) : K_ZERO) >= target) lo = mid; else hi = mid;
        }
        O->tau = (hi + lo) * K_HALF;
    } else {
        O->tau = tmin;
    }
    thr = net_threshold(B);
    B->tau = O->tau;
    gp4b_arc_end_constants(B);
    ht = gp4b_net_crossing_height(B);
    if (ht >= thr || !planned) {
        O->raised = 0;
        O->tau_raised = O->tau;
    } else {
        float spread;
        int round = 0;
        lo = B->tau;
        hi = tmin;
        B->tau = tmin;
        gp4b_arc_end_constants(B);
        ht = gp4b_net_crossing_height(B);
        O->net_unreachable = 0;
        if (ht < thr) {
            O->net_unreachable = 1;
            hi = tmin + K_FIVE;
            B->tau = hi;
            gp4b_arc_end_constants(B);
            ht = gp4b_net_crossing_height(B);
        }
        spread = K_ONE;
        while (spread > K_X_EPS) {
            float w;
            for (i = 0; i < 4; i++) {
                mid = (hi + lo) * K_HALF;
                B->tau = mid;
                gp4b_arc_end_constants(B);
                ht = gp4b_net_crossing_height(B);
                if (thr < ht) hi = B->tau; else lo = B->tau;
            }
            w = lo - hi;
            w = (w >= K_ZERO) ? w : -w;
            if (w < K_T_EPS) break;
            w = ht - thr;
            spread = (w >= K_ZERO) ? w : -w;
            if (++round >= 200) break;
        }
        O->raised = 1;
        O->tau_raised = (hi + lo) * K_HALF;
    }
    O->metric_kmh = (metric ? sqrtf(metric(B)) : sqrtf(K_ZERO)) * K_MS_TO_KMH;
    O->net_height = gp4b_net_crossing_height(B);
    if (planned) {
        float v2;
        gp4b_secondary_dispatch(B, tpl, O);
        v2 = gp4b_speed2_initial(B);
        O->initial_kmh = sqrtf(v2) * K_MS_TO_KMH;
        O->tau_final = B->tau;
    }
}

/* fn_888AD0E8: solver dispatch on the kind hash of template element 0 (tpl+0x08).  gp4b_arc_constants first. */
void gp4b_solve(Gp4bBall *B, const uint8_t *tpl, Gp4bSolve *O)
{
    uint32_t kind = be32(tpl + 0x08);
    gp4b_arc_constants(B);
    if (kind == TPLK_A) gp4b_solve_kind_time(B, tpl, O);
    else if (kind == TPLK_B) gp4b_solve_kind_speed(B, tpl, O, NULL);
    else if (kind == TPLK_C) gp4b_solve_kind_speed(B, tpl, O, gp4b_speed2_bounce);
    else if (kind == TPLK_D) gp4b_solve_kind_speed(B, tpl, O, gp4b_speed2_initial);
}

/* ------------------------------------------------------------------------------------------------------------- */
/* spin ("drift") vector                                                                                          */
/* ------------------------------------------------------------------------------------------------------------- */
/* fn_889C0DC0.  use_endpoints == 1 (launch / probe): d = P0 - P1 (3-D);  otherwise (after a bounce): d = arc2_vel with the
 * y component FORCED TO 0 (vrlimi128 ... 0x4: the previous notes missed this).  Returns without touching A when d == 0.
 * u = d / |d| : the original uses vrsqrtefp128 + one Newton step (hardware estimate), here 1/sqrtf: <= 1-2 ulp apart.
 * A = u * spin_c + c1 * (spin_b * sgn) + c2 * spin_a with c1 = u x up = (-u.z, 0, u.x), c2 = c1 x u,
 * sgn = sidespin_neg ? -1 : +1.  The vector multiply-adds are fused (vmaddfp), the first product is not. */
void gp4b_spin_accel(Gp4bBall *B, int use_endpoints)
{
    float d[3], u[3], c1[3], c2[3], len2, r, sb;
    float sgn = B->sidespin_neg ? -K_ONE : K_ONE;
    int i;
    if (use_endpoints == 1) {
        for (i = 0; i < 3; i++) d[i] = B->P0[i] - B->P1[i];
    } else {
        d[0] = B->arc2_vel[0]; d[1] = K_ZERO; d[2] = B->arc2_vel[2];
    }
    if (d[0] == K_ZERO && d[1] == K_ZERO && d[2] == K_ZERO) return;
    len2 = d[0] * d[0] + d[1] * d[1] + d[2] * d[2];
    r = K_ONE / sqrtf(len2);
    for (i = 0; i < 3; i++) u[i] = d[i] * r;
    c1[0] = fmaf(-u[2], K_ONE, u[1] * K_ZERO);
    c1[1] = fmaf(-u[0], K_ZERO, u[2] * K_ZERO);
    c1[2] = fmaf(-u[1], K_ZERO, u[0] * K_ONE);
    c2[0] = fmaf(-c1[2], u[1], c1[1] * u[2]);
    c2[1] = fmaf(-c1[0], u[2], c1[2] * u[0]);
    c2[2] = fmaf(-c1[1], u[0], c1[0] * u[1]);
    sb = B->spin_b * sgn;
    for (i = 0; i < 3; i++) {
        float t = fmaf(c1[i], sb, u[i] * B->spin_c);
        B->A[i] = fmaf(c2[i], B->spin_a, t);
    }
    B->A[3] = K_ZERO;
}

/* template spin element {i32 rel, u32 type}: type 0xF9F12A60 -> 20-byte-key curve evaluated at x, otherwise a plain float at e+rel */
static float spin_elem(const uint8_t *e, float x)
{
    int32_t rel = bei32(e);
    if (be32(e + 4) == NODE_CURVE20) return curve20_eval(x, e + rel);
    return bef32(e + rel);
}

/* fn_889C1868: spin_a/b/c = lerp(lo(x), hi(x), blend) with x = cmd_from.y (0x344, metres, the height of the hit point),
 * then gp4b_spin_accel(B, 1).  tpl+0x18 / +0x24 / +0x30 hold self-relative pointers to element PAIRS {lo, hi}: A -> spin_a, B -> spin_c, C -> spin_b. */
void gp4b_spin_blend(Gp4bBall *B, const uint8_t *tpl, float blend)
{
    float x = B->cmd_from[1];
    const uint8_t *pa = tpl + 0x18 + bei32(tpl + 0x18);
    const uint8_t *pb = tpl + 0x24 + bei32(tpl + 0x24);
    const uint8_t *pc = tpl + 0x30 + bei32(tpl + 0x30);
    float a_lo = spin_elem(pa, x), a_hi = spin_elem(pa + 8, x);
    float b_lo = spin_elem(pb, x), b_hi = spin_elem(pb + 8, x);
    float c_lo = spin_elem(pc, x), c_hi = spin_elem(pc + 8, x);
    B->spin_a = fmaf(a_hi - a_lo, blend, a_lo);
    B->spin_b = fmaf(c_hi - c_lo, blend, c_lo);
    B->spin_c = fmaf(b_hi - b_lo, blend, b_lo);
    gp4b_spin_accel(B, 1);
}

/* ------------------------------------------------------------------------------------------------------------- */
/* probe (fn_889C2678) and launch (fn_889C19F0)                                                                   */
/* ------------------------------------------------------------------------------------------------------------- */
/* fn_889C2678: the planner's shot solver.  Inputs in B: cmd_from/cmd_to (cm, world), tpl_offset is replaced by `row`
 * (pointer to the template row), radius_cm, shot_f430, blend, planned, speed_kmh / aim_height, net_height_cm, a4, g, shot_id,
 * sidespin_neg.  Outputs: B->tau, B->bounce_tick (the command's C+0x40 / C+0x44), *O, and a launch-ready B (P0/P1/pos/prev/origin).
 * `row` = S+0x3C table + B+0x360 (byte offset!); tpl = row + 0x18; T = row + 0x54. */
void gp4b_probe(Gp4bBall *B, const uint8_t *row, Gp4bSolve *O)
{
    const uint8_t *tpl = row + 0x18;
    float m_from[4], m_to[4], c_from[4], c_to[4];
    int i;
    O->probe = 1;
    for (i = 0; i < 3; i++) { m_from[i] = B->cmd_from[i] * K_CM_TO_M; m_to[i] = B->cmd_to[i] * K_CM_TO_M; }  /* fn_889C0F70 */
    m_from[3] = m_to[3] = K_ZERO;
    B->T = bef32(row + 0x54);
    for (i = 0; i < 4; i++) { B->P0[i] = m_from[i]; B->P1[i] = m_to[i]; }
    B->P0[1] = fmaf(-B->radius_cm, K_CM_TO_M, m_from[1]);   /* the ball centre starts one radius above the hit height */
    B->blend_c0c = B->shot_f430;
    B->blend_c10 = B->blend;
    B->cmd_from[0] = m_from[0]; B->cmd_from[1] = m_from[1]; B->cmd_from[2] = m_from[2]; B->cmd_from[3] = m_from[3];
    gp4b_spin_blend(B, tpl, B->blend);
    gp4b_solve(B, tpl, O);
    for (i = 0; i < 3; i++) { c_from[i] = m_from[i] * K_HUNDRED; c_to[i] = m_to[i] * K_HUNDRED; }
    c_from[3] = c_to[3] = K_ZERO;
    for (i = 0; i < 4; i++) { B->P0[i] = c_from[i]; B->P1[i] = c_to[i]; B->pos[i] = c_from[i]; B->prev[i] = c_from[i]; }
    B->origin[0] = K_ZERO; B->origin[1] = B->radius_cm; B->origin[2] = K_ZERO; B->origin[3] = K_ZERO;  /* local y = world y - radius */
    for (i = 0; i < 4; i++) { B->cmd_from[i] = c_from[i]; B->cmd_to[i] = c_to[i]; }                   /* fn_889C0EF8 */
}

/* net-interaction flags from the shot id / ball mode (fn_889C0C70, called by the launch with B->shot_id) */
#define HASH_LET_IN   0x8F903DFBu
#define HASH_LET_OUT  0x02315629u
#define HASH_NET      0xCAA7531Fu
#define HASH_OUT      0x81A72B79u
#define HASH_LIVE_A   0x9EA301C2u
#define HASH_LIVE_B   0x5D25ED1Du
#define HASH_OUT_B    0xCA68AAECu
void gp4b_mode_flags(Gp4bBall *B, uint32_t mode)
{
    if (B->bounce_count != 0) { B->flag33 = 0; B->flag32 = 1; B->flag31 = 1; return; }
    if (mode == HASH_WOOD || mode == HASH_NET) { B->flag33 = 0; B->flag32 = 1; B->flag31 = 1; return; }
    if (mode == HASH_LET_IN || mode == HASH_LET_OUT) { B->flag33 = 1; B->flag32 = 0; B->flag31 = 1; return; }
    if (mode == HASH_LIVE_A || mode == HASH_LIVE_B) { B->flag31 = B->flag32 = B->flag33 = 0; return; }
    if (mode == HASH_OUT || mode == HASH_OUT_B) {
        int same_side = (B->P1[0] * B->P0[0]) > K_ZERO;
        B->flag33 = 0;
        if (same_side) { B->flag32 = 1; B->flag31 = 1; } else { B->flag31 = 0; B->flag32 = 0; }
    }
}

/* fn_889C19F0 (live launch).  Preconditions (done by the command apply + fn_889C1160 / fn_889C0F70): P0/P1 already in the LOCAL
 * frame (metres, P0 and pos relative to origin), cmd_from scaled to metres (only y is used here), tau / bounce_tick from the command.
 * stepper_ticks_per_second = S+0x1C = 60.0.  Writes the arcs' constants, pos/prev = P0 and the landing frame. */
void gp4b_launch(Gp4bBall *B, const uint8_t *row, float ticks_per_second)
{
    const uint8_t *tpl = row + 0x18;
    B->bounce_count = 0; B->tick = 0; B->tick_prev = 0;
    B->T = bef32(row + 0x54);
    gp4b_mode_flags(B, B->shot_id);
    B->blend_c0c = B->shot_f430;
    B->blend_c10 = B->blend;
    gp4b_spin_blend(B, tpl, B->blend);
    gp4b_arc_constants(B);
    gp4b_arc_end_constants(B);
    memcpy(B->pos, B->P0, 16); memcpy(B->prev, B->P0, 16);
    gp4b_velocity_launch(B, B->v_launch);
    gp4b_velocity_arrival(B, B->v_arrive);
    B->event_frame[3][0] = B->launch_frame + (int32_t)(ticks_per_second * B->tau);
}

/* fn_889C1160 / fn_889C0FE8: world (cm, absolute) <-> local (m, relative to origin).  The caller owns the S+0x40 "is local" flag. */
void gp4b_to_local(Gp4bBall *B)
{
    float *vs[4] = {B->pos, B->prev, B->P0, B->arc2_pos};
    float *ns[2] = {B->P1, B->arc2_vel};
    int k, i;
    for (k = 0; k < 4; k++) for (i = 0; i < 3; i++) vs[k][i] = (vs[k][i] - B->origin[i]) * K_CM_TO_M;
    for (k = 0; k < 4; k++) vs[k][3] = (vs[k][3] - B->origin[3]) * K_ZERO;
    for (k = 0; k < 2; k++) { for (i = 0; i < 3; i++) ns[k][i] = ns[k][i] * K_CM_TO_M; ns[k][3] = ns[k][3] * K_ZERO; }
}

void gp4b_to_world(Gp4bBall *B)
{
    float *vs[4] = {B->pos, B->prev, B->P0, B->arc2_pos};
    float *ns[2] = {B->P1, B->arc2_vel};
    int k, i;
    for (k = 0; k < 4; k++) for (i = 0; i < 3; i++) vs[k][i] = vs[k][i] * K_HUNDRED + B->origin[i];
    for (k = 0; k < 4; k++) vs[k][3] = vs[k][3] * K_ZERO + B->origin[3];
    for (k = 0; k < 2; k++) { for (i = 0; i < 3; i++) ns[k][i] = ns[k][i] * K_HUNDRED; ns[k][3] = ns[k][3] * K_ZERO; }
}

/* ------------------------------------------------------------------------------------------------------------- */
/* per-tick flight (ground bounce part of fn_889C1F70; net / let / hold are in gp4_ball_flight.c, section 1.4)       */
/* ------------------------------------------------------------------------------------------------------------- */
/* The caller increments B->tick BEFORE each call (fn_886AD1F0 / the frame step), starting from 0 at launch.
 * Bounce response (fn_889C1C80) is returned through `bounce_v` = incoming velocity (m/s): the caller applies gp4_bounce().
 * Returns 1 when a ground bounce happened this tick (B->bounce_count already incremented, B->tick_prev = B->tick).  [H]  */
int gp4b_step_flight(float ticks_per_second, float dt, Gp4bBall *B, float bounce_v[4])
{
    int first = (B->bounce_count == 0);
    int i;
    float prev[3];
    int bounce;
    memcpy(B->prev, B->pos, 16);
    for (i = 0; i < 3; i++) prev[i] = B->pos[i];
    if (first) gp4b_arc1_position(dt, B); else gp4b_arc2_position(dt, B);
    if (first) bounce = (B->tick >= (int32_t)B->bounce_tick);
    else bounce = !((B->pos[1] - prev[1]) > K_ZERO) && B->pos[1] < -1.1920929e-7f;   /* pool+0x784 */
    if (bounce) {
        if (first) {
            gp4b_velocity_arrival(B, bounce_v);
        } else {
            for (i = 0; i < 3; i++) bounce_v[i] = (B->pos[i] - prev[i]) * ticks_per_second;
            bounce_v[3] = K_ZERO;
        }
        B->bounce_count++;
        B->tick_prev = B->tick;
        if (first) { for (i = 0; i < 4; i++) B->pos[i] = B->P1[i]; }   /* snap to the planned landing point */
        if (B->max_bounces <= (uint32_t)B->bounce_count)
            B->event_frame[4][0] = B->launch_frame + B->tick + 1;      /* +0xD0: frame at which the point is decided / ball dead */
    }
    for (i = 0; i < 4; i++) B->vel[i] = (B->pos[i] - B->prev[i]) * ticks_per_second;
    return bounce;
}

