static uint32_t fbits(float f) { uint32_t u; memcpy(&u, &f, 4); return u; }

static int run_gold(void)
{
    size_t i;
    int bad = 0;
    for (i = 0; i < sizeof gold_solve / sizeof gold_solve[0]; i++) {
        const GoldSolve *g = &gold_solve[i];
        Gp4bBall B;
        Gp4bSolve *O;
        uint8_t tpl[0x400];
        const float *in = g->in;
        const uint32_t *cst;
        int j, ok = 1;
        memset(&B, 0, sizeof B);
        memcpy(tpl, g->tpl, sizeof tpl);
        B.T = in[0]; B.blend_c0c = in[1]; B.a4 = in[2]; B.g = in[3]; B.radius_cm = in[4]; B.net_height_cm = in[5];
        B.aim_height = in[6]; B.speed_kmh = in[7];
        for (j = 0; j < 3; j++) { B.P0[j] = in[8 + j]; B.P1[j] = in[11 + j]; B.A[j] = in[14 + j]; }
        B.planned = g->planned; B.shot_id = g->shot_id;
        gp4b_solve(&B, tpl + 0x18, &B.res_a);
        O = &B.res_a;
        cst = (const uint32_t *)&B.inv_T;
        if (fbits(B.tau) != g->tau || B.bounce_tick != g->tick) ok = 0;
        for (j = 0; j < 18; j++) {                       /* +0x150 .. +0x197: cached closed-form constants */
            uint32_t w; memcpy(&w, (const char *)cst + 4 * j, 4);
            if (w != g->cst[j]) ok = 0;
        }
        if (fbits(O->tau) != g->resf[0] || fbits(O->tau_raised) != g->resf[1] || fbits(O->metric_kmh) != g->resf[2] ||
            fbits(O->tau_min) != g->resf[3] || fbits(O->tau_final) != g->resf[4] || fbits(O->initial_kmh) != g->resf[5] ||
            fbits(O->net_height) != g->resf[6]) ok = 0;
        if (O->raised != g->resb[0] || O->has_min != g->resb[1] || O->net_unreachable != g->resb[2]) ok = 0;
        printf("solve kind %08X/%08X planned=%d : tau=%.6f tick=%u initial=%.3f km/h net_h=%.4f m  %s\n", (unsigned)g->k0, (unsigned)g->k1,
               g->planned, B.tau, (unsigned)B.bounce_tick, O->initial_kmh, O->net_height, ok ? "OK (bit-exact vs original code)" : "MISMATCH");
        bad += !ok;
    }
    return bad;
}

/* physical consistency of the closed form: arc 1 reaches P1 exactly at t = tau and the launch velocity is its derivative */
static int run_consistency(void)
{
    Gp4bBall B;
    float v0[4], dt, p[3][3];
    int bad = 0, n = 60, i;
    double err;
    memset(&B, 0, sizeof B);
    B.T = 1.0f; B.a4 = 1.5f; B.g = 9.81f;
    B.P0[0] = -11.0f; B.P0[1] = 1.0f; B.P0[2] = 0.5f;
    B.P1[0] = 9.0f;   B.P1[1] = 0.0f; B.P1[2] = -2.0f;
    B.A[0] = 0.4f; B.A[1] = 0.8f; B.A[2] = -0.3f;
    B.tau = 1.0f;
    gp4b_arc_constants(&B);
    gp4b_arc_end_constants(&B);
    dt = B.tau / (float)n;
    for (i = 0; i < 3; i++) {
        B.tick_prev = 0; B.tick = (i == 0) ? 0 : (i == 1 ? 1 : n);
        gp4b_arc1_position(dt, &B);
        p[i][0] = B.pos[0]; p[i][1] = B.pos[1]; p[i][2] = B.pos[2];
    }
    err = fabs(p[2][0] - B.P1[0]) + fabs(p[2][1] - B.P1[1]) + fabs(p[2][2] - B.P1[2]);
    printf("arc1(t=tau) = (%.4f, %.4f, %.4f), planned landing (%.4f, %.4f, %.4f)  |err|=%.2e  %s\n", p[2][0], p[2][1], p[2][2],
           B.P1[0], B.P1[1], B.P1[2], err, err < 2e-3 ? "OK" : "FAIL");
    bad += !(err < 2e-3);
    err = fabs(p[0][0] - B.P0[0]) + fabs(p[0][1] - B.P0[1]) + fabs(p[0][2] - B.P0[2]);
    bad += !(err < 1e-4);
    gp4b_velocity_launch(&B, v0);
    err = fabs((p[1][0] - p[0][0]) / dt - v0[0]) / 1.0 + fabs((p[1][1] - p[0][1]) / dt - v0[1]) + fabs((p[1][2] - p[0][2]) / dt - v0[2]);
    printf("launch velocity (%.3f, %.3f, %.3f) m/s vs first tick difference: sum |diff| = %.3f (curvature over one tick)  %s\n",
           v0[0], v0[1], v0[2], err, err < 2.0 ? "OK" : "FAIL");
    bad += !(err < 2.0);
    return bad;
}

/* two-step probe + launch + tick loop on a hand-built template, printing the trajectory of the first arc */
static int run_flight(void)
{
    uint8_t row[0x400];
    Gp4bBall B;
    Gp4bSolve O;
    float bv[4];
    int t, bad = 0, bounced = 0;
    memset(row, 0, sizeof row);
    memset(&B, 0, sizeof B);
    memset(&O, 0, sizeof O);
    {   /* template: tau curve (cm -> s): one key; element kinds TPLK_A; spin: all constants */
        uint8_t *x = row;
        float v = 1.1f; uint32_t u;
#define PUT32(off, val) do { uint32_t q_ = (val); x[(off)] = (uint8_t)(q_ >> 24); x[(off) + 1] = (uint8_t)(q_ >> 16); x[(off) + 2] = (uint8_t)(q_ >> 8); x[(off) + 3] = (uint8_t)q_; } while (0)
        memcpy(&u, &v, 4); PUT32(0x54, 0x3F800000u);                 /* T = 1.0 */
        /* curve20 at 0x100: header {8, 1}, key {0, 5000, 1.1, 0, 0} */
        PUT32(0x100, 8); PUT32(0x104, 1); PUT32(0x108, 0); PUT32(0x10C, 0x459C4000u); PUT32(0x110, u); PUT32(0x114, 0);
        PUT32(0x18 + 0x00, 0x100 - 0x18); PUT32(0x18 + 0x04, NODE_CURVE20); PUT32(0x18 + 0x08, TPLK_A);
        PUT32(0x18 + 0x0C, 0x120 - 0x24); PUT32(0x18 + 0x10, NODE_CONST); PUT32(0x18 + 0x14, TPLK_A);
        PUT32(0x120, 0);                                              /* secondary offset curve value 0.0 */
        /* spin pairs at 0x130 (all constants, 0x140 holds the float values 0.0 / 2.0) */
        PUT32(0x140, 0); PUT32(0x144, 0x40000000u);
        PUT32(0x130, 0x140 - 0x130); PUT32(0x134, NODE_CONST); PUT32(0x138, 0x144 - 0x138); PUT32(0x13C, NODE_CONST);
        PUT32(0x18 + 0x18, 0x130 - (0x18 + 0x18)); PUT32(0x18 + 0x24, 0x130 - (0x18 + 0x24)); PUT32(0x18 + 0x30, 0x130 - (0x18 + 0x30));
    }
    B.a4 = 1.5f; B.g = 9.81f; B.radius_cm = 3.3f; B.net_height_cm = 91.4f;
    B.cmd_from[0] = -1100.0f; B.cmd_from[1] = 110.0f; B.cmd_from[2] = 40.0f;
    B.cmd_to[0] = 900.0f; B.cmd_to[1] = 0.0f; B.cmd_to[2] = -150.0f;
    B.blend = 0.5f; B.planned = 1; B.shot_id = 0x12345678u; B.shot_f430 = 0.0f; B.launch_frame = 100;
    gp4b_probe(&B, row, &O);
    printf("probe: tau=%.4f s (%u ticks)  initial speed %.1f km/h  net height %.3f m  raised=%d\n", B.tau, (unsigned)B.bounce_tick,
           O.initial_kmh, O.net_height, O.raised);
    gp4b_to_local(&B);
    gp4b_launch(&B, row, 60.0f);
    for (t = 0; t <= (int)B.bounce_tick + 1 && !bounced; t++) {
        B.tick = t;
        bounced = gp4b_step_flight(60.0f, K_TICK_DT, &B, bv);
        if (t % 10 == 0 || bounced)
            printf("tick %3d  pos(m) = (%8.3f, %7.3f, %7.3f)  speed %.2f m/s%s\n", t, B.pos[0], B.pos[1], B.pos[2],
                   sqrtf(B.vel[0] * B.vel[0] + B.vel[1] * B.vel[1] + B.vel[2] * B.vel[2]), bounced ? "  <- first bounce" : "");
    }
    if (!bounced) bad++;
    else bad += (fabsf(B.pos[0] - B.P1[0]) > 1e-4f || fabsf(B.pos[2] - B.P1[2]) > 1e-4f);
    printf("landing at planned point: %s\n", bad ? "FAIL" : "OK");
    return bad;
}

int main(void)
{
    int bad = 0;
    bad += run_gold();
    bad += run_consistency();
    bad += run_flight();
    printf(bad ? "SELFTEST FAILED (%d)\n" : "SELFTEST PASSED\n", bad);
    return bad != 0;
}

#endif
